CREATE OR REPLACE FUNCTION public.guard_student_academic_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_course uuid; BEGIN IF auth.uid() IS NULL OR NEW.student_id<>auth.uid() THEN RETURN NEW; END IF; IF TG_TABLE_NAME='enrollments' THEN IF NEW.status<>'pending' THEN RAISE EXCEPTION 'Enrollment requires teacher approval'; END IF; RETURN NEW; END IF; IF TG_TABLE_NAME='homework_submissions' THEN IF NEW.grade IS NOT NULL OR NEW.feedback IS NOT NULL THEN RAISE EXCEPTION 'Only the teacher may grade homework'; END IF; SELECT t.course_id INTO v_course FROM homework h JOIN topics t ON t.id=h.topic_id WHERE h.id=NEW.homework_id; ELSE SELECT course_id INTO v_course FROM topics WHERE id=NEW.topic_id AND deleted_at IS NULL; END IF; IF NOT EXISTS(SELECT 1 FROM enrollments WHERE student_id=auth.uid() AND course_id=v_course AND status='approved') THEN RAISE EXCEPTION 'Approved enrollment required'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_student_academic_insert() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER guard_student_insert BEFORE INSERT ON public.enrollments FOR EACH ROW EXECUTE FUNCTION public.guard_student_academic_insert();
CREATE TRIGGER guard_student_insert BEFORE INSERT ON public.homework_submissions FOR EACH ROW EXECUTE FUNCTION public.guard_student_academic_insert();
CREATE TRIGGER guard_student_insert BEFORE INSERT ON public.topic_progress FOR EACH ROW EXECUTE FUNCTION public.guard_student_academic_insert();
CREATE OR REPLACE FUNCTION public.replace_course_knowledge(p_course uuid,p_rows jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_count integer; BEGIN IF NOT EXISTS(SELECT 1 FROM courses WHERE id=p_course) OR jsonb_typeof(p_rows)<>'array' THEN RAISE EXCEPTION 'Invalid course index'; END IF; PERFORM pg_advisory_xact_lock(hashtext(p_course::text)); DELETE FROM course_chunks WHERE course_id=p_course; INSERT INTO course_chunks(course_id,topic_id,content,embedding,metadata) SELECT p_course,(r->>'topic_id')::uuid,r->>'content',(r->>'embedding')::extensions.vector,coalesce(r->'metadata','{}'::jsonb) FROM jsonb_array_elements(p_rows) r; GET DIAGNOSTICS v_count=ROW_COUNT; RETURN v_count; END $$;
REVOKE ALL ON FUNCTION public.replace_course_knowledge(uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.replace_course_knowledge(uuid,jsonb) TO service_role;